toolScript:
let map;
        let heatLayer;
        let allPoints = []; // Array of [lat, lon, intensity, timestamp]
        let isPlaying = false;
        let playInterval;
        // Demo Data Generator
        function loadDemo() {
            const points = [];
            let lat = 40.7128;
            let lon = -74.0060;
            const now = Date.now();
            for (let i = 0; i < 800; i++) {
                lat += (Math.random() - 0.5) * 0.015;
                lon += (Math.random() - 0.5) * 0.015;
                points.push([lat, lon, 0.8, now - (i * 3600000)]);
            }
            processPoints(points);
            showToast("Simulated data loaded locally.");
        }
        function handleFile(input) {
            if (input.files && input.files[0]) {
                const file = input.files[0];
                document.getElementById('loading').classList.remove('hidden');
                const reader = new FileReader();
                reader.onload = function (e) {
                    try {
                        const json = JSON.parse(e.target.result);
                        const points = [];
                        const rawData = json.locations || [];
                        // Limit to 15k points for performance balance
                        const step = Math.ceil(rawData.length / 15000) || 1;
                        for (let i = 0; i < rawData.length; i += step) {
                            const p = rawData[i];
                            const lat = p.latitudeE7 / 1e7;
                            const lon = p.longitudeE7 / 1e7;
                            const time = new Date(p.timestamp).getTime();
                            if (lat && lon) {
                                points.push([lat, lon, 0.5, time]);
                            }
                        }
                        processPoints(points);
                        showToast("Audit buffer populated.");
                    } catch (err) {
                        alert("Error parsing JSON. Ensure it is a valid Google Takeout Location History file (Records.json).");
                        document.getElementById('loading').classList.add('hidden');
                    }
                };
                reader.readAsText(file);
            }
        }
        function processPoints(points) {
            allPoints = points.sort((a, b) => a[3] - b[3]);
            document.getElementById('upload-view').classList.add('hidden');
            document.getElementById('viz-view').classList.remove('hidden');
            // Stats
            document.getElementById('stat-points').innerText = allPoints.length.toLocaleString();
            const start = new Date(allPoints[0][3]).getFullYear();
            const end = new Date(allPoints[allPoints.length - 1][3]).getFullYear();
            document.getElementById('stat-range').innerText = `${start} - ${end}`;
            // Init Map
            if (!map) {
                map = L.map('map', {
                    zoomControl: false,
                    attributionControl: false
                }).setView([allPoints[0][0], allPoints[0][1]], 10);
                L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
                    attribution: '&copy; CARTO'
                }).addTo(map);
                L.control.zoom({ position: 'bottomright' }).addTo(map);
            } else {
                map.setView([allPoints[0][0], allPoints[0][1]], 10);
            }
            updateHeatmap(allPoints);
        }
        function updateHeatmap(data) {
            if (heatLayer) map.removeLayer(heatLayer);
            heatLayer = L.heatLayer(data.map(p => [p[0], p[1], p[2]]), {
                radius: 12,
                blur: 15,
                maxZoom: 10,
                gradient: { 0.4: '#3b82f6', 0.6: '#06b6d4', 0.7: '#10b981', 0.8: '#facc15', 1.0: '#ef4444' }
            }).addTo(map);
        }
        function filterByTime(val) {
            const cutoffIndex = Math.floor((val / 100) * allPoints.length);
            const subset = allPoints.slice(0, cutoffIndex || 1);
            updateHeatmap(subset);
            const currentDate = new Date(subset[subset.length - 1][3]);
            document.getElementById('slider-label').innerText = currentDate.toLocaleDateString();
        }
        function togglePlay() {
            const slider = document.getElementById('time-slider');
            const btn = document.getElementById('play-btn');
            if (isPlaying) {
                clearInterval(playInterval);
                isPlaying = false;
                btn.innerHTML = '<svg class="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path></svg>';
            } else {
                if (parseInt(slider.value) === 100) slider.value = 0;
                isPlaying = true;
                btn.innerHTML = '<svg class="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clip-rule="evenodd"></path></svg>';
                playInterval = setInterval(() => {
                    let val = parseInt(slider.value);
                    if (val >= 100) {
                        togglePlay();
                        return;
                    }
                    slider.value = val + 1;
                    filterByTime(slider.value);
                }, 60);
            }
        }
        function resetTool() {
            if (!confirm("Purge current audit buffer?")) return;
            document.getElementById('viz-view').classList.add('hidden');
            document.getElementById('upload-view').classList.remove('hidden');
            document.getElementById('loading').classList.add('hidden');
            document.getElementById('file-input').value = '';
            if (isPlaying) togglePlay();
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[1100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // --- SCROLL LOGIC ---
